CREATE TABLE IF NOT EXISTS employee_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id),full_name TEXT NOT NULL,private_json TEXT NOT NULL DEFAULT '{}',photo_key TEXT,source_pages TEXT NOT NULL DEFAULT '[]',updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS employee_photos(photo_key TEXT PRIMARY KEY,mime_type TEXT NOT NULL,data_base64 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile_imports(id TEXT PRIMARY KEY,full_name TEXT NOT NULL,private_json TEXT NOT NULL,source_pages TEXT NOT NULL,photo_key TEXT,state TEXT NOT NULL DEFAULT 'pending',matched_user_id TEXT REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activity_sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),section TEXT NOT NULL,visible INTEGER NOT NULL,focused INTEGER NOT NULL,idle_seconds INTEGER NOT NULL,last_seen TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_activity_seen ON activity_sessions(user_id,last_seen);
CREATE TABLE IF NOT EXISTS activity_events(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),section TEXT NOT NULL,event TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_activity_event_time ON activity_events(created_at);
CREATE TABLE IF NOT EXISTS marketing_reports(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),summary TEXT NOT NULL,completed TEXT NOT NULL,blockers TEXT NOT NULL,next_steps TEXT NOT NULL,message_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS email_deliveries(notification_id TEXT PRIMARY KEY REFERENCES notifications(id),status TEXT NOT NULL CHECK(status IN ('sending','sent','skipped','failed','needs_review')),recipient TEXT NOT NULL,attempted_at TEXT NOT NULL,sent_at TEXT,error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS integration_status(provider TEXT PRIMARY KEY,status TEXT NOT NULL,account_label TEXT NOT NULL DEFAULT '',automation_id TEXT,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS uploads(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),context_type TEXT NOT NULL,context_id TEXT NOT NULL,filename TEXT NOT NULL,mime_type TEXT NOT NULL,size INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS upload_chunks(upload_id TEXT NOT NULL REFERENCES uploads(id),part INTEGER NOT NULL,data_base64 TEXT NOT NULL,PRIMARY KEY(upload_id,part));
CREATE TABLE IF NOT EXISTS grievance_comments(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES grievances(id),user_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meeting_deliveries(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id),user_id TEXT NOT NULL REFERENCES users(id),channel TEXT NOT NULL,event TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',recipient TEXT NOT NULL DEFAULT '',provider_id TEXT,error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,sent_at TEXT,UNIQUE(meeting_id,user_id,channel,event));
CREATE TABLE IF NOT EXISTS member_connections(user_id TEXT NOT NULL REFERENCES users(id),provider TEXT NOT NULL,account TEXT NOT NULL,status TEXT NOT NULL,verified_at TEXT,updated_at TEXT NOT NULL,PRIMARY KEY(user_id,provider));
CREATE TABLE IF NOT EXISTS oauth_states(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS whatsapp_challenges(user_id TEXT PRIMARY KEY REFERENCES users(id),phone TEXT NOT NULL,code_hash TEXT NOT NULL,expires_at TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,sent_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO app_settings(key,value) VALUES('require_connections','false');
INSERT OR IGNORE INTO channels(id,name,description,department,posting_policy,created_at) VALUES('marketing-reports','marketing-reports','Marketing progress, blockers and reports to Harsh.','Marketing','members',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE IF NOT EXISTS identity_documents(id TEXT PRIMARY KEY,import_id TEXT NOT NULL REFERENCES profile_imports(id),source_page INTEGER NOT NULL,mime_type TEXT NOT NULL,size INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(import_id,source_page));
CREATE TABLE IF NOT EXISTS identity_document_chunks(document_id TEXT NOT NULL REFERENCES identity_documents(id),part INTEGER NOT NULL,data_base64 TEXT NOT NULL,PRIMARY KEY(document_id,part));
CREATE TABLE IF NOT EXISTS work_notification_deliveries(id TEXT PRIMARY KEY,notification_id TEXT NOT NULL REFERENCES notifications(id),user_id TEXT NOT NULL REFERENCES users(id),channel TEXT NOT NULL,category TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'blocked',recipient TEXT NOT NULL DEFAULT '',provider_id TEXT,error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,sent_at TEXT,UNIQUE(notification_id,user_id,channel));
CREATE INDEX IF NOT EXISTS idx_work_notification_queue ON work_notification_deliveries(channel,status,created_at);
INSERT OR IGNORE INTO app_settings(key,value) VALUES('work_notifications_enabled_at',strftime('%Y-%m-%dT%H:%M:%fZ','now'));

CREATE INDEX IF NOT EXISTS idx_notifications_created ON notifications(created_at,id);
